class Value:
    def __init__(self, value):
        self._value = value

    def value(self):
        return self._value

    def add(self, x):
        return self._value + x

    def multiply(self, x):
        return self._value * x

    @staticmethod
    def max(values):
        if not values:
            return None
        max_value = values[0]
        for v in values[1:]:
            if v.value() > max_value.value():
                max_value = v
        return max_value

